using System.Globalization;
using System.Text;
using Microsoft.CodeAnalysis.CSharp;

namespace Moonwell.Build
{
    /// <summary>
    /// Writes the C# that registers each of the map's save classes with the code that writes and reads it (decision 180), as
    /// the game's Lua has almost no reflection: <c>SaveData.g.cs</c> in the generated folder, which only CSharp.lua compiles.
    /// </summary>
    public static class SaveCodecWriter
    {
        /// <summary>The generated file's name.</summary>
        public const string FileName = "SaveData.g.cs";

        /// <summary>The install line that registers the save classes.</summary>
        public const string Install = "global::Moonwell.Generated.SaveData.Register();";

        /// <summary>
        /// Writes the save code of a map with save classes, after checking its key and its record file, and gives the install
        /// line; removes the file an earlier build wrote and gives none for a map without.
        /// </summary>
        /// <exception cref="BuildException">The map has a save class and no SaveKey, or its record stops the build.</exception>
        public static IReadOnlyList<string> Write(string assemblyPath, MapProject project, MapSettings settings)
        {
            var classes = SaveClasses.Read(assemblyPath);
            if (classes.Count == 0)
            {
                Delete(project);
                return Array.Empty<string>();
            }

            if (settings.SaveKey.Length == 0)
            {
                throw new BuildException($"{classes[0].Name} is a save class, so the map needs a SaveKey: set SaveKey = \"a long private text, never changed\" in the constructor of {settings.TypeName} in Map.cs. Every save's check covers it, so a save loads only in this map");
            }

            SaveRecord.Keep(project, classes, settings.SaveKey, FileStore.FolderOf(settings, project));
            Directory.CreateDirectory(project.GeneratedFolder);
            File.WriteAllText(Path.Combine(project.GeneratedFolder, FileName), Code(classes));
            return new[] { Install };
        }

        /// <summary>Removes the file an earlier build wrote, which would not compile once the classes are gone.</summary>
        public static void Delete(MapProject project)
        {
            var path = Path.Combine(project.GeneratedFolder, FileName);
            if (File.Exists(path))
            {
                File.Delete(path);
            }
        }

        /// <summary>The generated file's text.</summary>
        public static string Code(IReadOnlyList<SaveClass> classes)
        {
            var index = new Dictionary<string, int>(StringComparer.Ordinal);
            for (var i = 0; i < classes.Count; i++)
            {
                index[classes[i].Name] = i;
            }

            var text = new StringBuilder();
            text.Append("// Generated by Moonwell's build. Do not edit; every build writes it anew.\n");
            text.Append("#nullable disable\n");
            text.Append("namespace Moonwell.Generated\n");
            text.Append("{\n");
            text.Append("    /// <summary>Registers the code that writes and reads each of the map's save classes.</summary>\n");
            text.Append("    public static class SaveData\n");
            text.Append("    {\n");
            text.Append("        /// <summary>Runs in the register step, before the map's components are added.</summary>\n");
            text.Append("        public static void Register()\n");
            text.Append("        {\n");
            for (var i = 0; i < classes.Count; i++)
            {
                if (!classes[i].IsPart)
                {
                    var type = TypeName(classes[i].Name);
                    text.Append($"            global::Moonwell.SaveGame.Register<{type}>({Quote(classes[i].Id)}, () => new {type}(), Write{i}, Read{i});\n");
                }
            }

            text.Append("        }\n");
            for (var i = 0; i < classes.Count; i++)
            {
                var type = TypeName(classes[i].Name);
                text.Append('\n');
                text.Append($"        private static void Write{i}({type} save, global::Moonwell.SaveWriter writer)\n");
                text.Append("        {\n");
                foreach (var member in classes[i].Members)
                {
                    text.Append("            ").Append(WriteLine(member, index)).Append('\n');
                }

                text.Append("        }\n");
                text.Append('\n');
                text.Append($"        private static void Read{i}({type} save, global::Moonwell.SaveReader reader)\n");
                text.Append("        {\n");
                text.Append("            while (reader.Next())\n");
                text.Append("            {\n");
                text.Append("                switch (reader.Number)\n");
                text.Append("                {\n");
                foreach (var member in classes[i].Members)
                {
                    text.Append($"                    case {member.Number.ToString(CultureInfo.InvariantCulture)}:\n");
                    text.Append("                        ").Append(ReadLine(member, index)).Append('\n');
                    text.Append("                        break;\n");
                }

                text.Append("                    default:\n");
                text.Append("                        reader.Skip();\n");
                text.Append("                        break;\n");
                text.Append("                }\n");
                text.Append("            }\n");
                text.Append("        }\n");
            }

            text.Append("    }\n");
            text.Append("}\n");
            return text.ToString();
        }

        private static string WriteLine(SavedMember member, IReadOnlyDictionary<string, int> index)
        {
            var number = member.Number.ToString(CultureInfo.InvariantCulture);
            var value = "save." + Identifier(member.Name);
            var type = member.Type;
            if (type.Stored == "part")
            {
                return $"writer.{(type.List ? "PartList" : "Part")}({number}, {value}, Write{index[type.Name!]});";
            }

            if (type.IsEnum && type.List)
            {
                return $"if ({value} != null) {{ var ints = new global::System.Collections.Generic.List<int>(); foreach (var one in {value}) {{ ints.Add((int)one); }} writer.IntList({number}, ints); }}";
            }

            if (type.IsEnum)
            {
                return $"writer.Int({number}, (int){value});";
            }

            return $"writer.{Method(type.Stored)}{(type.List ? "List" : string.Empty)}({number}, {value});";
        }

        private static string ReadLine(SavedMember member, IReadOnlyDictionary<string, int> index)
        {
            var value = "save." + Identifier(member.Name);
            var type = member.Type;
            var array = type.Array ? ".ToArray()" : string.Empty;
            if (type.Stored == "part")
            {
                var made = $"() => new {TypeName(type.Name!)}()";
                return type.List
                    ? $"{{ var read = reader.PartList({made}, Read{index[type.Name!]}); if (read != null) {{ {value} = read{array}; }} }}"
                    : $"{value} = reader.Part({value}, {made}, Read{index[type.Name!]});";
            }

            if (type.IsEnum && type.List)
            {
                var list = $"global::System.Collections.Generic.List<{TypeName(type.Name!)}>";
                return $"{{ var ints = reader.IntList(); if (ints != null) {{ var read = new {list}(); foreach (var one in ints) {{ read.Add(({TypeName(type.Name!)})one); }} {value} = read{array}; }} }}";
            }

            if (type.IsEnum)
            {
                return $"{value} = ({TypeName(type.Name!)})reader.Int((int){value});";
            }

            if (type.List)
            {
                return $"{{ var read = reader.{Method(type.Stored)}List(); if (read != null) {{ {value} = read{array}; }} }}";
            }

            return $"{value} = reader.{Method(type.Stored)}({value});";
        }

        // A name may be a keyword, written @class in the map's code.
        private static string Identifier(string name)
        {
            return SyntaxFacts.GetKeywordKind(name) == SyntaxKind.None ? name : "@" + name;
        }

        private static string TypeName(string name)
        {
            return "global::" + string.Join(".", name.Split('.').Select(Identifier));
        }

        private static string Method(string stored)
        {
            return char.ToUpperInvariant(stored[0]) + stored.Substring(1);
        }

        private static string Quote(string text)
        {
            return "\"" + text.Replace("\\", "\\\\").Replace("\"", "\\\"") + "\"";
        }
    }
}
